fn equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Ensure both vectors have the same length
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");

    // Zip the two vectors together and compare element-wise,
    // collecting the boolean results into a new Vec<bool>.
    a.iter()
     .zip(b.iter())
     .map(|(x, y)| x == y)
     .collect()
}

fn main() {
    let a = vec![1, -2, 3, 0];
    let b = vec![1,  2, 3, 4];
    let result = equal(a, b);
    println!("{:?}", result); // prints: [true, false, true, false]
}